ALTER TABLE public.activities ADD COLUMN plan_added boolean NOT NULL DEFAULT false;
CREATE TABLE public.plan_coach_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), lesson_id uuid NOT NULL REFERENCES public.weekly_lessons(id) ON DELETE CASCADE, title text NOT NULL DEFAULT 'Plan conversation', messages jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.plan_coach_threads TO authenticated;
GRANT ALL ON public.plan_coach_threads TO service_role;
ALTER TABLE public.plan_coach_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_threads ON public.plan_coach_threads FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.weekly_lessons l WHERE l.id = lesson_id AND l.user_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.weekly_lessons l WHERE l.id = lesson_id AND l.user_id = auth.uid()));
CREATE TABLE public.weekly_plan_originals (lesson_id uuid PRIMARY KEY REFERENCES public.weekly_lessons(id) ON DELETE CASCADE, user_id uuid NOT NULL DEFAULT auth.uid(), days jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.weekly_plan_originals TO authenticated;
GRANT ALL ON public.weekly_plan_originals TO service_role;
ALTER TABLE public.weekly_plan_originals ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_original ON public.weekly_plan_originals FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE POLICY create_original ON public.weekly_plan_originals FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.weekly_lessons l WHERE l.id = lesson_id AND l.user_id = auth.uid()));
CREATE TABLE public.plan_coach_proposals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL DEFAULT auth.uid(), thread_id uuid NOT NULL REFERENCES public.plan_coach_threads(id) ON DELETE CASCADE, lesson_id uuid NOT NULL REFERENCES public.weekly_lessons(id) ON DELETE CASCADE, summary text NOT NULL, additions jsonb NOT NULL, status text NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.plan_coach_proposals TO authenticated;
GRANT ALL ON public.plan_coach_proposals TO service_role;
ALTER TABLE public.plan_coach_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_proposals ON public.plan_coach_proposals FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.plan_coach_threads t WHERE t.id = thread_id AND t.user_id = auth.uid() AND t.lesson_id = lesson_id));
CREATE TABLE public.plan_coach_access_blocks (user_id uuid PRIMARY KEY DEFAULT auth.uid(), message text NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.plan_coach_access_blocks TO authenticated;
GRANT ALL ON public.plan_coach_access_blocks TO service_role;
ALTER TABLE public.plan_coach_access_blocks ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_access_block ON public.plan_coach_access_blocks FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE OR REPLACE FUNCTION public.apply_plan_coach_proposal(proposal_id uuid, generated jsonb) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$
DECLARE p public.plan_coach_proposals; a jsonb; d public.study_days; next_position integer;
BEGIN
 SELECT * INTO p FROM public.plan_coach_proposals WHERE id = proposal_id AND user_id = auth.uid() FOR UPDATE;
 IF p.id IS NULL THEN RAISE EXCEPTION 'Plan change not found'; END IF;
 IF p.status = 'applied' THEN RETURN; END IF;
 PERFORM 1 FROM public.weekly_lessons WHERE id = p.lesson_id AND user_id = auth.uid() AND status IN ('planned', 'active') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Only an active study plan can be changed'; END IF;
 IF jsonb_array_length(generated) = 0 OR jsonb_array_length(generated) > 10 THEN RAISE EXCEPTION 'Invalid activities'; END IF;
 FOR a IN SELECT value FROM jsonb_array_elements(generated) LOOP
  SELECT * INTO d FROM public.study_days WHERE lesson_id = p.lesson_id AND user_id = auth.uid() AND day_number = (a->>'day')::integer FOR UPDATE;
  IF d.id IS NULL THEN RAISE EXCEPTION 'Study day not found'; END IF;
  IF (a->>'kind') NOT IN ('flashcards', 'listening', 'conversation', 'quiz') OR (a->>'est_minutes')::integer NOT BETWEEN 3 AND 60 THEN RAISE EXCEPTION 'Invalid activity'; END IF;
  SELECT greatest(1000, coalesce(max(position) + 1, 1000)) INTO next_position FROM public.activities WHERE day_id = d.id;
  INSERT INTO public.activities(user_id, lesson_id, day_id, position, kind, title, description, source, est_minutes, content, plan_added) VALUES (auth.uid(), p.lesson_id, d.id, next_position, a->>'kind', a->>'title', a->>'description', 'ai', (a->>'est_minutes')::integer, a->'content', true);
  UPDATE public.study_days SET target_minutes = greatest(60, target_minutes) + (a->>'est_minutes')::integer, completed_at = NULL WHERE id = d.id;
 END LOOP;
 UPDATE public.plan_coach_proposals SET status = 'applied' WHERE id = p.id;
END $$;
REVOKE ALL ON FUNCTION public.apply_plan_coach_proposal(uuid, jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.apply_plan_coach_proposal(uuid, jsonb) TO authenticated;
